import{_ as l,a0 as o,w as r,s as c,I as e,x as s,a1 as i,A as n,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"使用 Cockpit 管理你的樹莓派 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Cockpit 管理你的樹莓派 | LCTT (202106) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Cockpit 管理你的樹莓派 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Cockpit 管理你的樹莓派 | LCTT (202106) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202106/20210518 Manage your Raspberry Pi with Cockpit","title":"使用 Cockpit 管理你的樹莓派","tag":"202106","desc":""},"relativePath":"202106/20210518 Manage your Raspberry Pi with Cockpit.md","filePath":"[post].md"}'),d={name:"202106/20210518 Manage your Raspberry Pi with Cockpit.md"};function h(k,a,u,m,b,g){const t=o("Link");return r(),c("div",null,[a[21]||(a[21]=e("h1",{id:"使用-cockpit-管理你的樹莓派",tabindex:"-1"},[s("使用 Cockpit 管理你的樹莓派 "),e("a",{class:"header-anchor",href:"#使用-cockpit-管理你的樹莓派","aria-label":"Permalink to “使用 Cockpit 管理你的樹莓派”"},"​")],-1)),a[22]||(a[22]=e("blockquote",null,[e("p",null,"用 Cockpit 建立你的樹莓派的控制中心。")],-1)),a[23]||(a[23]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202106/15/144053hmswm01w6qus011n.jpg",alt:""})],-1)),e("p",null,[a[1]||(a[1]=s("去年，我寫了關於使用 ",-1)),i(t,{href:"https://opensource.com/article/20/11/cockpit-server-management"},{default:n(()=>[...a[0]||(a[0]=[s("Cockpit 管理我的 Linux 服務器的文章",-1)])]),_:1}),a[2]||(a[2]=s("。它是一個基於 Web 的工具，為管理多個服務器及其相關的服務和應用提供了一個簡潔、強大的界面。它還簡化了日常的管理任務。",-1))]),a[24]||(a[24]=p(`<p>在這篇文章中，我將會介紹如何在樹莓派基金會提供的標準操作系統樹莓派 OS 上安裝用於 Linux 服務器的 Cockpit Web 控制台。我還會簡要介紹它的特性。</p><h3 id="在樹莓派-os-上安裝-cockpit" tabindex="-1">在樹莓派 OS 上安裝 Cockpit <a class="header-anchor" href="#在樹莓派-os-上安裝-cockpit" aria-label="Permalink to “在樹莓派 OS 上安裝 Cockpit”">​</a></h3><p>在 <code>sudo</code> 權限下使用一個賬户通過 SSH 登錄你的樹莓派系統。如果你還沒有建立一個賬户：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh pibox</span></span>
<span class="line"><span>alan@pibox&#39;s password:</span></span>
<span class="line"><span>Linux pibox.someplace.org 5.10.17-v7+ #1403 SMP Mon Feb 22 11:29:51 GMT 2021 armv7l</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The programs included with the Debian GNU/Linux system are free software;</span></span>
<span class="line"><span>the exact distribution terms for each program are described in the</span></span>
<span class="line"><span>individual files in /usr/share/doc/*/copyright.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Debian GNU/Linux comes with ABSOLUTELY NO WARRANTY, to the extent</span></span>
<span class="line"><span>permitted by applicable law.</span></span>
<span class="line"><span>Last login: Tue May  4 09:55:57 2021 from 172.1.4.5</span></span>
<span class="line"><span>alan@pibox:~ $</span></span></code></pre></div><p>在樹莓派 OS 上安裝 Cockpit Web 控制台和在 Linux 服務器上一樣簡單：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install cockpit</span></span></code></pre></div><p>Cockpit 只需要 60.4 KB 的磁盤空間。加上它的幾個包依賴項，總使用量是 115MB。</p><p>安裝過程將負責設置和啓動服務。你可以使用 <code>systemctl</code> 命令來驗證狀態：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl status cockpit.socket</span></span>
<span class="line"><span>● cockpit.socket - Cockpit Web Service Socket</span></span>
<span class="line"><span>   Loaded: loaded (/lib/systemd/system/cockpit.socket; enabled; vendor preset: enabled)</span></span>
<span class="line"><span>   Active: active (listening) since Tue 2021-05-04 10:24:43 EDT; 35s ago</span></span>
<span class="line"><span>     Docs: man:cockpit-ws(8)</span></span>
<span class="line"><span>   Listen: 0.0.0.0:9090 (Stream)</span></span>
<span class="line"><span>  Process: 6563 ExecStartPost=/usr/share/cockpit/motd/update-motd  localhost (code=exited, status=0/SUCCESS)</span></span>
<span class="line"><span>  Process: 6570 ExecStartPost=/bin/ln -snf active.motd /run/cockpit/motd (code=exited, status=0/SUCCESS)</span></span>
<span class="line"><span>    Tasks: 0 (limit: 2181)</span></span>
<span class="line"><span>   CGroup: /system.slice/cockpit.socket</span></span></code></pre></div><h3 id="使用-cockpit" tabindex="-1">使用 Cockpit <a class="header-anchor" href="#使用-cockpit" aria-label="Permalink to “使用 Cockpit”">​</a></h3><h4 id="連接" tabindex="-1">連接 <a class="header-anchor" href="#連接" aria-label="Permalink to “連接”">​</a></h4><p>默認的監聽端口號是 9090。打開你最喜歡的 Web 瀏覽器並輸入地址，例如： <code>https://pibox:9090</code>。</p><p><img src="https://opensource.com/sites/default/files/uploads/cockpit_homepage.png" alt="Cockpit home page" title="Cockpit home page"></p><p>你現在可以使用你的普通賬户登錄。同樣，這個賬户上需要有使用 <code>sudo</code> 的權限 —— 很可能就是你用來 SSH 和運行 Apt 的那個賬户。一定要勾選“為特權任務重用我的密碼”。</p><h4 id="管理你的樹莓派" tabindex="-1">管理你的樹莓派 <a class="header-anchor" href="#管理你的樹莓派" aria-label="Permalink to “管理你的樹莓派”">​</a></h4><p>Cockpit 的初始屏幕以 “System” 頁開始，提供當前 CPU 和內存使用的詳細信息和圖表。</p><p><img src="https://opensource.com/sites/default/files/uploads/cockpit_initialscreen.png" alt="Initial Cockpit screen" title="Initial Cockpit screen"></p><p>你可以從這個屏幕看到硬件細節。</p><p><img src="https://opensource.com/sites/default/files/uploads/hardware_details.png" alt="Cockpit hardware details" title="Cockpit hardware details"></p><p>通過點擊每一項來展開左邊的列（例如，日誌、存儲、服務等）。這些是標準的 Cockpit 部分，不言自明。讓我快速描述一下每個部分。</p><h4 id="日誌" tabindex="-1">日誌 <a class="header-anchor" href="#日誌" aria-label="Permalink to “日誌”">​</a></h4><p>這部分展示了日誌。它們可以根據日期和嚴重程度來過濾。</p><h4 id="存儲" tabindex="-1">存儲 <a class="header-anchor" href="#存儲" aria-label="Permalink to “存儲”">​</a></h4><p>存儲部分展示了已經安裝的物理驅動器和 RAID 設備。例如大小、序列號等細節都被展示了出來。還展示了讀/寫活動和實際空間使用的圖表。存儲的具體日誌顯示在底部。</p><h4 id="網絡" tabindex="-1">網絡 <a class="header-anchor" href="#網絡" aria-label="Permalink to “網絡”">​</a></h4><p>這部分展示了發送和接收活動、IP 地址以及網絡特定的日誌。你還可以使用相應的按鈕添加更多的網絡設備，如綁定、網橋和 VLAN。</p><h4 id="賬户" tabindex="-1">賬户 <a class="header-anchor" href="#賬户" aria-label="Permalink to “賬户”">​</a></h4><p>這裏展示了已有的賬户。點擊每個賬户來管理，或使用創建新賬户按鈕來添加用户。賬户也可以被刪除。</p><h4 id="服務" tabindex="-1">服務 <a class="header-anchor" href="#服務" aria-label="Permalink to “服務”">​</a></h4><p>這部分可以讓管理員查看系統所有服務的狀態。點擊任何服務都會轉到一個包含啓動、重啓和禁用的標準任務的屏幕。</p><h4 id="應用程序" tabindex="-1">應用程序 <a class="header-anchor" href="#應用程序" aria-label="Permalink to “應用程序”">​</a></h4><p>通常，這個屏幕提供了各種用於管理功能的應用程序，例如 389 目錄服務器或創建 Podman 容器。但在我的樹莓派 OS 上，這個屏幕只顯示“沒有安裝或可用的應用程序”。在寫這篇文章的時候，這個或許還沒有實現。雖然，你可能會懷疑這類型的程序對於樹莓派硬件來説是否太過沉重。</p><h4 id="軟件更新" tabindex="-1">軟件更新 <a class="header-anchor" href="#軟件更新" aria-label="Permalink to “軟件更新”">​</a></h4><p>對任何系統管理員來説，保持軟件最新是最重要的任務之一。Cockpit 的軟件更新部分可以檢查並進行更新。</p><p><img src="https://opensource.com/sites/default/files/uploads/software_updates.png" alt="Software updates in Cockpit" title="Software updates in Cockpit"></p><h4 id="終端" tabindex="-1">終端 <a class="header-anchor" href="#終端" aria-label="Permalink to “終端”">​</a></h4>`,36)),e("p",null,[a[4]||(a[4]=s("Cockpit 最方便的特點之一是終端。你可以使用它，而不是打開一個單獨的終端模擬器並使用 SSH。我使用終端來安裝 ",-1)),i(t,{href:"https://opensource.com/article/20/1/screenfetch-neofetch"},{default:n(()=>[...a[3]||(a[3]=[s("ScreenFetch",-1)])]),_:1}),a[5]||(a[5]=s("：",-1))]),a[25]||(a[25]=p('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install screenfetch</span></span></code></pre></div><p>使用 ScreenFetch 生成了這張截圖：</p><p><img src="https://opensource.com/sites/default/files/uploads/pi_cockpit_terminal.png" alt="Terminal in Cockpit" title="Terminal in Cockpit"></p><h3 id="使用-cockpit-的中心控制" tabindex="-1">使用 Cockpit 的中心控制 <a class="header-anchor" href="#使用-cockpit-的中心控制" aria-label="Permalink to “使用 Cockpit 的中心控制”">​</a></h3><p>Cockpit 在樹莓派上的表現就像它在其他 Linux 系統上一樣。你可以將它添加到儀表盤上進行集中控制。它允許企業在 Cockpit 作為管理儀表盤解決方案的任何地方，將基於樹莓派的服務和系統整合到他們的整體 Linux 基礎設施中。因為樹莓派經常在高密度機架數據中心以<ruby>無外接控制<rt>headless</rt></ruby>方式運行，而這些數據中心通常會缺乏 KVM 訪問方式，這是非常方便的。</p><hr>',6)),e("p",null,[a[7]||(a[7]=s("via: ",-1)),i(t,{href:"https://opensource.com/article/21/5/raspberry-pi-cockpit"},{default:n(()=>[...a[6]||(a[6]=[s("https://opensource.com/article/21/5/raspberry-pi-cockpit",-1)])]),_:1})]),e("p",null,[a[12]||(a[12]=s("作者：",-1)),i(t,{href:"https://opensource.com/users/alanfdoss"},{default:n(()=>[...a[8]||(a[8]=[s("Alan Formy-Duval",-1)])]),_:1}),a[13]||(a[13]=s(" 選題：",-1)),i(t,{href:"https://github.com/lujun9972"},{default:n(()=>[...a[9]||(a[9]=[s("lujun9972",-1)])]),_:1}),a[14]||(a[14]=s(" 譯者：",-1)),i(t,{href:"https://github.com/ShuyRoy"},{default:n(()=>[...a[10]||(a[10]=[s("RiaXu",-1)])]),_:1}),a[15]||(a[15]=s(" 校對：",-1)),i(t,{href:"https://github.com/wxy"},{default:n(()=>[...a[11]||(a[11]=[s("wxy",-1)])]),_:1})]),e("p",null,[a[18]||(a[18]=s("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...a[16]||(a[16]=[s("LCTT",-1)])]),_:1}),a[19]||(a[19]=s(" 原創編譯，",-1)),i(t,{href:"https://linux.cn/"},{default:n(()=>[...a[17]||(a[17]=[s("Linux中國",-1)])]),_:1}),a[20]||(a[20]=s(" 榮譽推出",-1))])])}const y=l(d,[["render",h]]);export{x as __pageData,y as default};
